  ns.decodeDem = function decodeDem(b64, expectedLen) {
    const bin = atob(b64);
    const out = new Uint8Array(expectedLen);
    let pos = 0;
    for (let i = 0; i < bin.length && pos < expectedLen; i++) {
      const b = bin.charCodeAt(i);
      if (b & 0x80) {
        const count = b & 0x7f;
        const val = bin.charCodeAt(++i);
        for (let k = 0; k < count && pos < expectedLen; k++) out[pos++] = val;
      } else {
        out[pos++] = b;
      }
    }
    return out;
  };
